var schemeName = Tama.Args.Get(args, "scheme", "");
var targetTitle = Tama.Args.Get(args, "target", "");
var paramName = Tama.Args.Get(args, "param", "Comments");
Document target = null;
foreach (Document d in app.Documents) if (!d.IsLinked && d.Title == targetTitle) target = d;
if (target == null) throw new InvalidOperationException("The target model is not open: " + targetTitle);
Func<Document, string, object> summ = (Document d, string pname) => new FilteredElementCollector(d).OfCategory(BuiltInCategory.OST_Areas).WhereElementIsNotElementType().Cast<Autodesk.Revit.DB.Area>()
  .Where(a => a.AreaScheme != null && a.AreaScheme.Name == schemeName)
  .GroupBy(a => (a.Level?.Name ?? "-") + " | " + a.get_Parameter(BuiltInParameter.ROOM_NAME).AsString())
  .Select(g => new { key = g.Key, count = g.Count(), vals = string.Join(" / ", g.Select(a => a.LookupParameter(pname)?.AsString() ?? "").Distinct()) })
  .OrderBy(x => x.key).ToList();
return new { source = summ(doc, paramName), target = summ(target, paramName) };
